const params=new URLSearchParams(window.location.search),productId=params.get("id");let quantity=1;const quantityText=document.getElementById("quantity"),totalPriceText=document.getElementById("total-price");fetch(`https://fakestoreapi.com/products/${productId}`).then(t=>t.json()).then(t=>{let e=document.getElementById("detail-image");e.src=t.image,e.loading="lazy",e.decoding="async",document.getElementById("detail-title").textContent=t.title,document.getElementById("detail-description").textContent=t.description;let n=t.price;totalPriceText.textContent=n.toFixed(2),document.getElementById("increase").addEventListener("click",()=>{quantity++,quantityText.textContent=quantity,totalPriceText.textContent=(n*quantity).toFixed(2)}),document.getElementById("decrease").addEventListener("click",()=>{quantity>1&&(quantity--,quantityText.textContent=quantity,totalPriceText.textContent=(n*quantity).toFixed(2))}),document.getElementById("add-cart-btn").addEventListener("click",()=>{let e=JSON.parse(localStorage.getItem("cart"))||[];e.push({...t,quantity:quantity,totalPrice:n*quantity,size:document.getElementById("size-select").value,color:document.getElementById("color-select").value}),localStorage.setItem("cart",JSON.stringify(e)),alert("Product added to cart!")})}).catch(t=>{console.log("Error loading product:",t)});